-- วันที่ส่งครบของออเดอร์เก่า = กำหนดส่ง (ไม่มี = เดือนที่สั่ง)
update public.corp_orders set delivered_at = coalesce(due_date, order_date) where status = 'delivered' and delivered_at = (now() at time zone 'Asia/Bangkok')::date and created_at > now() - interval '1 minute';
alter table public.corp_orders enable trigger corp_order_audit;
insert into public.corp_order_log (order_id, message)
  select o.id, 'นำเข้าจาก Google Sheet ลูกค้า Corporate' from public.corp_orders o
   where not exists (select 1 from public.corp_order_log l where l.order_id = o.id);
